// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /admin/v1/admins)
	ListAdmins(w http.ResponseWriter, r *http.Request)
	// 新建管理员，返回一次性初始密码
	// (POST /admin/v1/admins)
	CreateAdmin(w http.ResponseWriter, r *http.Request)

	// (PATCH /admin/v1/admins/{adminId})
	UpdateAdmin(w http.ResponseWriter, r *http.Request, adminId AdminId)
	// 重置密码，返回一次性新密码
	// (POST /admin/v1/admins/{adminId}/reset-password)
	ResetAdminPassword(w http.ResponseWriter, r *http.Request, adminId AdminId)
	// 审计日志
	// (GET /admin/v1/audit-log)
	ListAuditLog(w http.ResponseWriter, r *http.Request, params ListAuditLogParams)
	// 邮箱密码登录
	// (POST /admin/v1/auth/login)
	AdminLogin(w http.ResponseWriter, r *http.Request)
	// 工作副本相对线上版本的改动（发布前的 diff）
	// (GET /admin/v1/config/changes)
	ListConfigChanges(w http.ResponseWriter, r *http.Request)
	// 配置项（工作副本），附线上版本的值
	// (GET /admin/v1/config/keys)
	ListConfigKeys(w http.ResponseWriter, r *http.Request, params ListConfigKeysParams)
	// 新建配置项（owner）。新建后要发布才会下发
	// (POST /admin/v1/config/keys)
	CreateConfigKey(w http.ResponseWriter, r *http.Request)

	// (GET /admin/v1/config/keys/{key})
	GetConfigKey(w http.ResponseWriter, r *http.Request, key ConfigKeyName)
	// 修改工作副本。改命名空间、归档需要 owner；类型不能改
	// (PATCH /admin/v1/config/keys/{key})
	UpdateConfigKey(w http.ResponseWriter, r *http.Request, key ConfigKeyName)
	// 某个用户 / 设备会拿到什么值、命中哪条规则
	// (POST /admin/v1/config/preview)
	PreviewConfig(w http.ResponseWriter, r *http.Request)
	// 发布记录，最新在前
	// (GET /admin/v1/config/releases)
	ListConfigReleases(w http.ResponseWriter, r *http.Request, params ListConfigReleasesParams)
	// 提交发布。按审批规则直接上线（status=published）或等待审批（status=pending）
	// (POST /admin/v1/config/releases)
	SubmitConfigRelease(w http.ResponseWriter, r *http.Request)
	// 发布详情。已发布的与上一个发布版本比较，待审批的与当前线上版本比较
	// (GET /admin/v1/config/releases/{releaseId})
	GetConfigRelease(w http.ResponseWriter, r *http.Request, releaseId ReleaseId)
	// 审批并上线（owner；不能审批自己提交的，除非只有一个 owner）
	// (POST /admin/v1/config/releases/{releaseId}/approve)
	ApproveConfigRelease(w http.ResponseWriter, r *http.Request, releaseId ReleaseId)
	// 驳回待审批的发布（owner）
	// (POST /admin/v1/config/releases/{releaseId}/reject)
	RejectConfigRelease(w http.ResponseWriter, r *http.Request, releaseId ReleaseId)
	// 把这个已发布版本的内容作为新版本重新发布，同时把工作副本恢复成它（审批规则同提交）
	// (POST /admin/v1/config/releases/{releaseId}/rollback)
	RollbackConfigRelease(w http.ResponseWriter, r *http.Request, releaseId ReleaseId)
	// 内置工具与 MCP 白名单（含已下架）
	// (GET /admin/v1/connectors)
	ListConnectors(w http.ResponseWriter, r *http.Request)
	// 上下架、默认开启、排序与展示文案。新增 MCP 服务需要改代码（catalog.yaml）后发布
	// (PATCH /admin/v1/connectors/{connectorId})
	UpdateConnector(w http.ResponseWriter, r *http.Request, connectorId string)
	// 成本：按天、按模型、按任务类型、最高成本用户
	// (GET /admin/v1/costs)
	GetCosts(w http.ResponseWriter, r *http.Request, params GetCostsParams)
	// 运营概览（按 Asia/Shanghai 计日）
	// (GET /admin/v1/dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request)
	// 当前管理员
	// (GET /admin/v1/me)
	GetAdminMe(w http.ResponseWriter, r *http.Request)
	// 修改自己的密码
	// (POST /admin/v1/me/password)
	ChangeAdminPassword(w http.ResponseWriter, r *http.Request)
	// 模型网关路由与单价（读自 ZEUS_MODELGW_CONFIG，只读；修改需改文件并重启）及近 24 小时调用
	// (GET /admin/v1/modelgw)
	GetModelGateway(w http.ResponseWriter, r *http.Request)
	// 拦截记录
	// (GET /admin/v1/moderation/events)
	ListModerationEvents(w http.ResponseWriter, r *http.Request, params ListModerationEventsParams)
	// 屏蔽词（与 ZEUS_MODERATION_KEYWORDS_FILE 合并生效，约 1 分钟内同步到各进程）
	// (GET /admin/v1/moderation/terms)
	ListModerationTerms(w http.ResponseWriter, r *http.Request)

	// (POST /admin/v1/moderation/terms)
	CreateModerationTerm(w http.ResponseWriter, r *http.Request)

	// (DELETE /admin/v1/moderation/terms/{termId})
	DeleteModerationTerm(w http.ResponseWriter, r *http.Request, termId int64)
	// 方案与额度（代码内配置，只读）
	// (GET /admin/v1/plans)
	ListPlans(w http.ResponseWriter, r *http.Request)
	// 查看报告正文（审核用）
	// (GET /admin/v1/reports/{reportId})
	GetReport(w http.ResponseWriter, r *http.Request, reportId string)
	// 公开分享的报告
	// (GET /admin/v1/shares)
	ListShares(w http.ResponseWriter, r *http.Request, params ListSharesParams)
	// 撤销分享链接
	// (POST /admin/v1/shares/{shareId}/revoke)
	RevokeShare(w http.ResponseWriter, r *http.Request, shareId string)
	// 全部任务
	// (GET /admin/v1/tasks)
	ListTasks(w http.ResponseWriter, r *http.Request, params ListTasksParams)
	// 任务详情与模型调用明细
	// (GET /admin/v1/tasks/{taskId})
	GetTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// 取消运行中的任务
	// (POST /admin/v1/tasks/{taskId}/cancel)
	CancelTask(w http.ResponseWriter, r *http.Request, taskId TaskId)
	// 模板列表；official 为官方模板，custom 为用户自定义模板（用于审核）
	// (GET /admin/v1/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, params ListTemplatesParams)
	// 新建官方模板
	// (POST /admin/v1/templates)
	CreateTemplate(w http.ResponseWriter, r *http.Request)
	// 删除模板（已订阅的简报保留，但与模板解除关联；官方模板建议改为下架）
	// (DELETE /admin/v1/templates/{templateId})
	DeleteTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)

	// (GET /admin/v1/templates/{templateId})
	GetTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// 修改模板。官方模板改过后不再被 `zeusctl seed` 覆盖；字段、栏目或来源变化时版本号加 1
	// (PUT /admin/v1/templates/{templateId})
	UpdateTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// 用户列表
	// (GET /admin/v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// 用户详情（额度、定时简报、近 30 天成本）
	// (GET /admin/v1/users/{userId})
	GetUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// 修改会员方案
	// (PATCH /admin/v1/users/{userId})
	UpdateUserPlan(w http.ResponseWriter, r *http.Request, userId UserId)
	// 停用账号（注销登录态，暂停其定时简报）
	// (POST /admin/v1/users/{userId}/disable)
	DisableUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// 恢复账号（恢复因停用而暂停的定时简报）
	// (POST /admin/v1/users/{userId}/enable)
	EnableUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// 清除额度覆盖
	// (DELETE /admin/v1/users/{userId}/quota)
	ClearUserQuota(w http.ResponseWriter, r *http.Request, userId UserId)
	// 设置额度覆盖（字段为空表示沿用方案额度）
	// (PUT /admin/v1/users/{userId}/quota)
	SetUserQuota(w http.ResponseWriter, r *http.Request, userId UserId)
}

